INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT159-S3-Q15$batch02$, 159, 3, 15, $batch02$Flaw$batch02$, $batch02$Schmidt: In enforcing township rules on how homeowners maintain their property, it is a mistake to encourage residents to report violations by their neighbors. Doing so engenders bad feelings among neighbors and leads to tips based on spite. Chandha: It’s not a mistake. Without rules on how homeowners maintain their property, a single homeowner could degrade the appearance of an entire neighborhood.$batch02$, $batch02$Chandha’s response is most vulnerable to criticism on the grounds that it$batch02$, $batch02$A$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q15$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$takes a criticism of the way in which certain rules are enforced to be a criticism of the rules themselves$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$challenges the motivation behind Schmidt’s argument rather than Schmidt’s reasoning$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$confuses a criticism of the consequences of having a set of rules with a criticism of the detailed provisions of the rules$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$takes for granted that just because something is likely to happen on some occasions, it will always happen$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$confuses the cause of bad feelings among neighbors with a consequence of bad feelings among neighbors$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Schmidt's claim$batch02$, $batch02$In *enforcing* the rules, encouraging neighbors to report each other is a mistake.$batch02$), (1, $batch02$Chandha's conclusion$batch02$, $batch02$It is not a mistake.$batch02$), (2, $batch02$Chandha's evidence$batch02$, $batch02$Without the rules, one homeowner could ruin a neighborhood's appearance.$batch02$), (3, $batch02$Evaluate$batch02$, $batch02$Schmidt never said the township should drop the rules. Schmidt objected to one *way of enforcing* them. Chandha defends the rules' existence. Agree that speed limits are good; that does not mean paying neighbors to report each other's speeding is a good idea. Chandha answers a position Schmidt never took.$batch02$), (4, $batch02$Goal$batch02$, $batch02$Look for the shift from criticizing enforcement to defending the rules.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$Schmidt criticizes a method of enforcement. Chandha responds as if Schmidt had criticized the rules themselves. Showing the rules are valuable does not show neighbor reporting is a good way to enforce them.$batch02$), ($batch02$B$batch02$, $batch02$Chandha says nothing about why Schmidt holds the view. The response is about the rules' value.$batch02$), ($batch02$C$batch02$, $batch02$Neither speaker discusses the rules' detailed provisions. Schmidt's complaint is about enforcement, which (A) captures.$batch02$), ($batch02$D$batch02$, $batch02$Chandha does not reason from "likely sometimes" to "always." "Could degrade" is a possibility.$batch02$), ($batch02$E$batch02$, $batch02$Chandha never discusses bad feelings among neighbors at all, so there is no cause and effect to confuse.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT159-S3-Q15$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
